// 商品一覧を1時間キャッシュ
export async function ProductList() {
  'use cache';
  cacheLife('hours');
  cacheTag('products');

  const products = await fetchProducts(); // サーバー側で直接フェッチ
  return (
    <ul>
      {products.map(p => <ProductCard key={p.id} product={p} />)}
    </ul>
  );
}

// ユーザープロフィール（動的レンダリング）
export async function UserProfile({ userId }: { userId: string }) {
  // キャッシュなし（cookies()やheaders()を使用）
  const session = await getSession();
  const user = await fetchUser(userId);

  return (
    <div>
      <h1>{user.name}</h1>
      <p>{user.email}</p>
    </div>
  );
}

// ユーザー操作時のデータフェッチ
'use client';

import { useQuery } from '@tanstack/react-query';
import { searchProducts } from '@/apis/products.client';

export function SearchResults({ query }: { query: string }) {
  const { data, isLoading, error } = useQuery({
    queryKey: ['products', 'search', query],
    queryFn: () => searchProducts(query), // Route Handlerを経由
    enabled: query.length > 0,
  });

  if (isLoading) return <Loading />;
  if (error) return <Error message={error.message} />;

  return (
    <ul>
      {data?.products.map(p => <ProductCard key={p.id} product={p} />)}
    </ul>
  );
}

// app/api/products/search/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { searchProductsFromAPI } from '@/apis/products.server';

export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams;
  const query = searchParams.get('query');

  if (!query) {
    return NextResponse.json(
      { error: 'Query parameter is required' },
      { status: 400 }
    );
  }

  try {
    // サーバー側のAPIクライアントを使用（APIキーは環境変数から取得）
    const products = await searchProductsFromAPI(query);
    return NextResponse.json({ products });
  } catch (error) {
    console.error('Search error:', error);
    return NextResponse.json(
      { error: 'Failed to search products' },
      { status: 500 }
    );
  }
}

// apis/products.server.ts
export async function searchProductsFromAPI(query: string) {
  const apiKey = process.env.EXTERNAL_API_KEY; // 環境変数から取得
  const response = await fetch(
    `https://api.example.com/products/search?q=${query}`,
    {
      headers: {
        'Authorization': `Bearer ${apiKey}`,
      },
    }
  );

  if (!response.ok) {
    throw new Error('Failed to search products');
  }

  return response.json();
}

// apis/products.client.ts
export async function searchProducts(query: string) {
  // Route Handlerを経由（APIキーを露出しない）
  const response = await fetch(`/api/products/search?query=${query}`);

  if (!response.ok) {
    throw new Error('Failed to search products');
  }

  return response.json();
}

// データが必要なコンポーネントで直接フェッチ
export async function ProductDetails({ productId }: { productId: string }) {
  'use cache';
  cacheLife('hours');
  cacheTag('products', `product-${productId}`);

  // このコンポーネントで直接データをフェッチ（props drillingを避ける）
  const product = await fetchProduct(productId);

  return (
    <div>
      <h1>{product.name}</h1>
      <p>{product.description}</p>
      <ProductReviews productId={productId} /> {/* 関連データも個別にフェッチ */}
    </div>
  );
}

async function ProductReviews({ productId }: { productId: string }) {
  'use cache';
  cacheLife('minutes');
  cacheTag('reviews', `reviews-${productId}`);

  // レビューデータも個別にフェッチ（Request Memoizationで重複排除）
  const reviews = await fetchReviews(productId);

  return (
    <ul>
      {reviews.map(r => <ReviewCard key={r.id} review={r} />)}
    </ul>
  );
}

// page.tsx
export default function ProductPage({ params }: { params: { id: string } }) {
  return (
    <div>
      {/* 静的部分は即座に表示 */}
      <Header />

      {/* 動的部分はSuspenseでラップ */}
      <Suspense fallback={<ProductSkeleton />}>
        <ProductDetails productId={params.id} />
      </Suspense>

      <Suspense fallback={<ReviewsSkeleton />}>
        <ProductReviews productId={params.id} />
      </Suspense>
    </div>
  );
}
